where id = 207 and language = 'en' and description_en is null and md5(description) = '61926590dbffc90fd91ef2116fbba5ba';

-- 208 ernest-hemingway-selected-letters-1917-1961
update public.books set description_en = description, description = $mota$Nhiều người biết đến hình ảnh công chúng của Hemingway và những câu chuyện huyền thoại về cuộc đời ông, nhưng ít ai biết ông như một người thân thiết. Giờ đây, với tuyển tập thư này, tuyển tập đầu tiên được xuất bản, một Hemingway mới hiện ra. Trải dài từ năm 1917 đến 1961, tuyển chọn phong phú gần 600 bức thư này thực chất vừa là một bức chân dung tự họa, vừa là một cuốn tự truyện.$mota$, description_auto_translated = true
where id = 208 and language = 'en' and description_en is null and md5(description) = '674a22e9769b6428dc724fd5a978cf2d';

