update public.books set description_en = description, description = $mota$Bức tranh kinh điển về tình yêu và bạo lực trong thập niên 1920.$mota$, description_auto_translated = true
where id = 209 and language = 'en' and description_en is null and md5(description) = '06d729398fefca6fe07b4e4259366b9c';

-- 210 7-best-short-stories-by-f-scott-fitzgerald
update public.books set description_en = description, description = $mota$Trong thế giới của Fitzgerald, mọi thứ ngọt ngào đều hóa đắng; bữa tiệc nào cũng là một bi kịch. Thoạt đầu, mọi thứ có vẻ quyến rũ, xa hoa và ngập trong rượu champagne. Nhưng khi tiếng nhạc dừng, tất cả sụp đổ. Tiền là khởi đầu và kết thúc của mọi rắc rối, và thế giới bị chia cắt rạch ròi giữa những người có tiền và những người cần tiền. Hãy du hành qua vũ trụ phong phú của nhà văn lớn này qua bảy truyện ngắn được chọn lọc đặc biệt để làm hài lòng cả độc giả lâu năm lẫn người mới đến với tác phẩm của Fitzgerald: The Diamond as Big as the Ritz; The Jelly-Bean; May Day; The Curious Case of Benjamin Button; Bernice Bobs Her Hair; Head and Shoulders; The Cut-Glass Bowl.$mota$, description_auto_translated = true
where id = 210 and language = 'en' and description_en is null and md5(description) = '7e86b1666006db7fb490f1311a69752e';

-- 211 fitzgerald-the-love-of-the-last-tycoon
update public.books set description_en = description, description = $mota$Ấn bản phê bình này của The Love of The Last Tycoon sử dụng các bản thảo viết tay, các bản đánh máy đã sửa và ghi chép làm việc của Fitzgerald.$mota$, description_auto_translated = true
where id = 211 and language = 'en' and description_en is null and md5(description) = '2f21ebbd6b0d8c7e3599a9a3cbc1011f';

-- 212 f-scott-fitzgerald-on-writing
update public.books set description_en = description, description = $mota$Tuyển tập những nhận xét của F. Scott Fitzgerald về nghề viết, trích từ tác phẩm và thư ông gửi bạn bè, đồng nghiệp: một kho lời khuyên không thể thiếu cho người muốn trở thành nhà văn. Như F. Scott Fitzgerald từng tuyên bố trong câu nói nổi tiếng: “Một tác giả nên viết cho tuổi trẻ thế hệ mình, cho giới phê bình thế hệ sau, và cho các thầy giáo mãi về sau.” Chính tác phẩm của Fitzgerald đã được bình luận và bàn luận suốt hơn một trăm năm. Kiệt tác The Great Gatsby của ông tràn đầy đam mê và sự xa hoa đặc trưng của Thời đại Jazz, thuật ngữ do chính Fitzgerald đặt ra. Những chủ đề ấy cũng in dấu cuộc đời ông: Fitzgerald nhập ngũ quân đội Mỹ trong Thế chiến I, nhờ vậy gặp người vợ tương lai Zelda khi đóng quân ở Alabama. Sau đó, cùng Ernest Hemingway và những nghệ sĩ Mỹ sống ở nước ngoài khác, ông trở thành một phần của “Thế hệ lạc lõng” ở châu Âu. Fitzgerald viết sách “để thỏa mãn khao khát của chính [mình] về một kiểu tiểu thuyết nhất định”, từ đó ra đời những tác phẩm kinh điển hiện đại của Mỹ như Tender Is the Night, This Side of Paradise, The Beautiful and Damned. Trong tuyển tập trích đoạn từ sách, bài báo và thư riêng gửi bạn bè, đồng nghiệp này, Fitzgerald khắc họa đời sống của người viết một cách vượt thời gian.$mota$, description_auto_translated = true
where id = 212 and language = 'en' and description_en is null and md5(description) = '4f61fded181f5254bdb98e79df9633fc';

-- 213 and-the-mountains-echoed
update public.books set description_en = description, description = $mota$Vậy thì. Con muốn nghe chuyện, ta sẽ kể cho con nghe một chuyện… Afghanistan, năm 1952. Abdullah và em gái Pari sống cùng cha và mẹ kế ở ngôi làng nhỏ Shadbagh. Cha của hai đứa, Saboor, luôn phải đi tìm việc, và cả nhà cùng chật vật qua cảnh nghèo khó và những mùa đông khắc nghiệt. Với Abdullah, Pari, xinh đẹp và hiền dịu như nàng tiên mà cô bé được đặt tên theo, là tất cả. Giống cha mẹ hơn là anh trai, Abdullah sẵn sàng làm mọi thứ vì em, kể cả đổi đôi giày duy nhất của mình lấy một chiếc lông vũ cho bộ sưu tập quý giá của em. Đêm nào hai anh em cũng ngủ chung trên chiếc giường nhỏ, đầu chạm đầu, tay chân quấn vào nhau. Một ngày nọ, hai anh em cùng cha vượt sa mạc đến Kabul. Pari và Abdullah không hề biết số phận nào đang chờ mình ở đó, bởi sự việc xảy ra sẽ xé nát cuộc đời họ; đôi khi phải cắt một ngón tay để cứu cả bàn tay. Vượt qua nhiều thế hệ và châu lục, từ Kabul đến Paris, San Francisco, rồi hòn đảo Tinos của Hy Lạp, với sự minh triết, chiều sâu, óc thấu hiểu và lòng trắc ẩn sâu sắc, Khaled Hosseini viết về những mối gắn bó định nghĩa và định hình cuộc đời ta, cách ta giúp đỡ người thân khi họ cần, cách những lựa chọn của ta vang vọng qua lịch sử, và cách ta thường bất ngờ trước chính những người gần gũi nhất. Mỗi ấn bản giới hạn có chữ ký này đều đi kèm hộp bìa vải thiết kế đẹp mắt.$mota$, description_auto_translated = true
where id = 213 and language = 'en' and description_en is null and md5(description) = '93eaccc1d8025c995c791853826f799c';

-- 214 the-kite-runner-4054
update public.books set description_en = description, description = $mota$Sách bán chạy số một. “Đau đớn tột cùng” (Daily Telegraph). “Xé lòng” (The Times). “Không thể nào quên” (Isabel Allende). “Ám ảnh” (Independent). Afghanistan, năm 1975: cậu bé mười hai tuổi Amir khao khát thắng giải đấu thả diều ở địa phương, và người bạn trung thành Hassan hứa sẽ giúp cậu. Nhưng cả hai đều không thể lường trước điều sẽ xảy đến với Hassan chiều hôm ấy, một sự việc sẽ làm tan nát cuộc đời họ. Sau khi quân Nga xâm lược và gia đình buộc phải chạy sang Mỹ, Amir nhận ra rằng một ngày nào đó cậu phải trở về Afghanistan dưới sự cai trị của Taliban để tìm thứ duy nhất mà thế giới mới không thể trao cho cậu: sự chuộc lỗi.$mota$, description_auto_translated = true
where id = 214 and language = 'en' and description_en is null and md5(description) = 'fcf06b0f3f088d8f9892832e5407bf42';

-- 215 the-complete-khaled-hosseini-box-set
update public.books set description_en = description, description = $mota$Trọn bộ ba tiểu thuyết bán chạy khắp thế giới của Khaled Hosseini trong một hộp sách đẹp: The Kite Runner, A Thousand Splendid Suns và And the Mountains Echoed.$mota$, description_auto_translated = true
